INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass die Verkabelung zu Endgeräten immer Kupferkabel verwendet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Glasfaser möglich"}, {"text": "Ja", "correct": false, "because": "Nicht auf Kupfer beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kabel wird häufig für die Verbindung zu Arbeitsplätzen genutzt?', 3, '[{"text": "Cat6", "correct": true, "because": "Unterstützt Gigabit-Ethernet"}, {"text": "Koaxialkabel", "correct": false, "because": "Für TV oder Breitband"}, {"text": "Telefonkabel", "correct": false, "because": "Eingeschränkte Bandbreite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards sind für die Verkabelung zu Endgeräten wichtig?', 5, '[{"text": "TIA/EIA-568-B", "correct": true, "because": "Definiert Verkabelung"}, {"text": "ISO/IEC 11801", "correct": true, "because": "Regelt Netzwerkstandards"}, {"text": "Farbcodierung", "correct": false, "because": "Nur Orientierungshilfe"}, {"text": "Bürodesign", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sekundärverkabelung verbindet Verteiler mit Endgeräten. b) Sie nutzt immer Glasfaser.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kupfer häufiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung der Verkabelung zu Endgeräten?', 4, '[{"text": "Kabellänge", "correct": false, "because": "Beeinflusst Signalqualität"}, {"text": "Anschlussarten", "correct": false, "because": "Bestimmen Kompatibilität"}, {"text": "Kabelbeschriftung", "correct": true, "because": "Nur organisatorisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Verkabelung immer RJ45-Anschlüsse nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Anschlüsse wie LC möglich"}, {"text": "Ja", "correct": false, "because": "Nicht immer RJ45"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard definiert die Belegung von Twisted-Pair-Kabeln?', 4, '[{"text": "T568-B", "correct": true, "because": "Regelt Pinbelegung"}, {"text": "IEEE 802.3", "correct": false, "because": "Für Ethernet-Protokolle"}, {"text": "USB-C", "correct": false, "because": "Andere Schnittstelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Verkabelung immer sichtbar verlegt wird. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Oft verdeckt in Wänden"}, {"text": "Ja", "correct": false, "because": "Verdeckte Verlegung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt Cat5e Gigabit-Ethernet?', 2, '[{"text": "Ja", "correct": true, "because": "Bis 1 Gbit/s geeignet"}, {"text": "Nein", "correct": false, "because": "Unterstützt Gigabit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Verkabelung zu Endgeräten?', 5, '[{"text": "Kabellänge", "correct": true, "because": "Beeinflusst Signal"}, {"text": "Kabeltyp", "correct": true, "because": "Bestimmt Bandbreite"}, {"text": "Verlegeart", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Kabelgewicht", "correct": false, "because": "Sekundär"}, {"text": "Bürofarben", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Planung der Verkabelung?', 4, '[{"text": "Zukunftssicherheit", "correct": true, "because": "Höhere Bandbreite unterstützen"}, {"text": "Schnelle Verlegung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cat6 unterstützt 10 Gigabit-Ethernet. b) Es ist für Telefonie ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch für Telefonie nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine zuverlässige Verkabelung?', 3, '[{"text": "Kabelschutz", "correct": false, "because": "Schützt vor Schäden"}, {"text": "Standardbelegung", "correct": false, "because": "Sichert Funktion"}, {"text": "Dekorative Ummantelung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Signalqualität der Verkabelung sichere?', 4, '[{"text": "Kabellänge begrenzen, Schirmung nutzen", "correct": true, "because": "Minimiert Störungen"}, {"text": "Nur lange Kabel nutzen", "correct": false, "because": "Schwächt Signal"}, {"text": "Ohne Schirmung", "correct": false, "because": "Erhöht Störungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Verkabelung immer ungeschirmt ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Geschirmte Kabel üblich"}, {"text": "Ja", "correct": false, "because": "Schirmung oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kabel unterstützt PoE (Power over Ethernet)?', 4, '[{"text": "Cat5e", "correct": true, "because": "Ermöglicht Stromversorgung"}, {"text": "Glasfaserkabel", "correct": false, "because": "Kein Stromtransport"}, {"text": "Koaxialkabel", "correct": false, "because": "Andere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Verkabelung immer für Datenübertragung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Strom via PoE"}, {"text": "Ja", "correct": false, "because": "Mehrzweck möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Cat7 gegenüber Cat6?', 5, '[{"text": "Höhere Bandbreite", "correct": true, "because": "Bis 10 Gbit/s über längere Strecken"}, {"text": "Bessere Schirmung", "correct": true, "because": "Reduziert Störungen"}, {"text": "Leichteres Gewicht", "correct": false, "because": "Kein Vorteil"}, {"text": "Farbliche Vielfalt", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verlegung der Verkabelung unwichtig?', 3, '[{"text": "Kabelführung", "correct": false, "because": "Vermeidet Störungen"}, {"text": "Anschlusskompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Kabelbeschriftung", "correct": true, "because": "Nur organisatorisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Verkabelung plane?', 4, '[{"text": "Kabellänge prüfen, Standards einhalten", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Nur Kabel stapeln", "correct": false, "because": "Fehlt Planung"}, {"text": "Ohne Standards", "correct": false, "because": "Riskiert Fehler"}]');
